<div class="inventory-page">@include('livewire.admin.inventory._nav')<div class="inventory-header"><h1>{{__('ui.inventory.scan')}}</h1></div><div class="inventory-card"><div id="reader" style="max-width:500px"></div><input class="form-control mt-3" wire:model="token" placeholder="SKU / Barcode / QR Token"><button class="btn btn-primary mt-2" wire:click="lookup">{{__('ui.inventory.view')}}</button></div>@if($item)<div class="inventory-card"><h2>{{$item->name_ar}}</h2><p>SKU: {{$item->sku}}</p><p>{{__('ui.inventory.reorder_level')}}: {{$item->reorder_level}}</p><a class="btn btn-outline-primary" href="{{route('admin.inventory.items.edit',$item)}}" wire:navigate>{{__('ui.inventory.edit')}}</a></div>@endif<script src="https://unpkg.com/html5-qrcode"></script><script>document.addEventListener('livewire:navigated',()=>{const r=document.getElementById('reader');if(!r||r.dataset.ready)return;r.dataset.ready=1;const q=new Html5Qrcode('reader');q.start({facingMode:'environment'},{fps:10,qrbox:250},t=>{ @this.set('token',t); @this.call('lookup'); q.stop(); });});</script></div>
